from returns.result import Success, Failure, safe

@safe
def parse_port(text: str) -> int:
    port = int(text)
    if not 0 < port < 65536:
        raise ValueError("port.out_of_range")
    return port

match parse_port(raw):
    case Success(value): start(value)
    case Failure(error): log.error("invalid port: %s", error)
